<?php foreach($requests??array() as $request): $letter=json_decode($request['Letter'],true); ?><option data-branch="<?= (int)$request['SpbbID'] ?>" value="<?= (int)$request['RequestID'] ?>" <?= (int)($workflow['RequestID']??0)===(int)$request['RequestID']?'selected':'' ?>><?= html_escape($request['RequestNo'].' / '.($letter['VesselName']??'').' / '.($letter['FillingDate']??'')) ?></option><?php endforeach; ?></select>
