<div class="box"><div class="box-header"><h3 class="box-title">100 SPP Terbaru</h3></div><div class="box-body table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Tanggal Upload</th><th>Cabang</th><th>File SPP</th><th>Nomor LO / SO</th><th>Pembeli</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($captures as $row): ?><tr><td><?= html_escape($row['CreatedAt']) ?></td><td><?= html_escape(isset($branchNames[$row['SpbbID']])?$branchNames[$row['SpbbID']]:$row['SpbbID']) ?></td><td><a target="_blank" rel="noopener" href="<?= site_url('Pipeline_spp/file/'.$row['CaptureID']) ?>"><?= html_escape($row['OriginalName']) ?></a></td><td><?= html_escape($row['LONumber'].' / '.$row['SONumber']) ?></td><td><?= html_escape($row['Buyer']) ?></td><td><span class="label label-<?= $row['Status']==='CONFIRMED'?'success':'warning' ?>"><?= $row['Status']==='CONFIRMED'?'Tersimpan':'Perlu diperiksa' ?></span></td><td><a class="btn btn-primary btn-sm" href="<?= site_url('Pipeline_spp/review/'.$row['CaptureID']) ?>">View / Hasil Bacaan</a> · <a href="<?= site_url('Pipeline_documents/edit/spp/'.(int)$row['CaptureID']) ?>">Edit</a><?php if($row['Status']==='CONFIRMED'&&!$row['DeliveryID']&&empty($row['ProposedRequestID'])): ?> · <a href="<?= site_url('Pipanisasi/delivery').'?spp='.(int)$row['CaptureID'] ?>">Buat / Upload DO Pipanisasi</a><?php endif; ?><?php if($row['DeliveryID']||$row['DocumentID']): ?> · <a href="<?= site_url('Pipeline_documents/spp_links/'.(int)$row['CaptureID']) ?>">Dokumen Terkait</a><?php else: ?><?php $action_type='spp';$action_id=(int)$row['CaptureID'];$this->load->view('pipeline/document_delete',compact('action_type','action_id')); ?><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$captures): ?><tr><td colspan="7">Belum ada foto SPP.</td></tr><?php endif; ?></tbody></table></div></div>
</section></div>
<script>(function(){var branch=document.getElementById('spp-branch'),delivery=document.getElementById('spp-request'),file=document.getElementById('spp-file'),photo=document.getElementById('spp-photo');function filter(){Array.prototype.forEach.call(delivery.options,function(o){if(!o.value)return;var show=o.getAttribute('data-branch')===branch.value;o.hidden=!show;o.disabled=!show;if(!show&&o.selected)delivery.value='';});if(window.jQuery)window.jQuery(delivery).trigger('change.select2');}branch.addEventListener('change',filter);filter();file.addEventListener('change',function(){if(file.files.length){photo.value='';document.getElementById('spp-photo-name').textContent='';}});photo.addEventListener('change',function(){if(photo.files.length){file.value='';document.getElementById('spp-photo-name').textContent=photo.files[0].name;}});document.getElementById('spp-upload-form').addEventListener('submit',function(e){if(!file.files.length&&!photo.files.length){e.preventDefault();alert('Pilih file atau ambil foto SPP terlebih dahulu.');return;}var btn=document.getElementById('spp-read');btn.disabled=true;btn.textContent='Sedang membaca SPP...';});})();</script>
